-- Create webhook_events table for tracking webhook processing and idempotency
CREATE TABLE IF NOT EXISTS webhook_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    gateway_name VARCHAR(50) NOT NULL,
    event_id VARCHAR(255) NOT NULL,
    event_type VARCHAR(100) NOT NULL,
    event_data JSONB NOT NULL,
    signature_verified BOOLEAN DEFAULT FALSE,
    processed_at TIMESTAMP WITH TIME ZONE,
    status VARCHAR(50) DEFAULT 'pending', -- pending, processed, failed, ignored
    payment_id UUID REFERENCES payments(id),
    program_registration_id UUID REFERENCES program_registrations(id),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    processing_attempts INTEGER DEFAULT 0,
    last_error TEXT,
    metadata JSONB DEFAULT '{}'::jsonb
);

-- Create unique index to prevent duplicate webhook processing
CREATE UNIQUE INDEX IF NOT EXISTS idx_webhook_events_gateway_event_id 
ON webhook_events(gateway_name, event_id);

-- Create indexes for efficient querying
CREATE INDEX IF NOT EXISTS idx_webhook_events_status ON webhook_events(status);
CREATE INDEX IF NOT EXISTS idx_webhook_events_created_at ON webhook_events(created_at);
CREATE INDEX IF NOT EXISTS idx_webhook_events_payment_id ON webhook_events(payment_id);
CREATE INDEX IF NOT EXISTS idx_webhook_events_event_type ON webhook_events(event_type);

-- Enable Row Level Security
ALTER TABLE webhook_events ENABLE ROW LEVEL SECURITY;

-- Create RLS policy for webhook_events (system-only access)
CREATE POLICY webhook_events_system_access ON webhook_events
    FOR ALL USING (true);

-- Add comments
COMMENT ON TABLE webhook_events IS 'Stores webhook events from payment gateways for idempotency and audit trail';
COMMENT ON COLUMN webhook_events.gateway_name IS 'Name of the payment gateway (stripe, paypal, etc.)';
COMMENT ON COLUMN webhook_events.event_id IS 'Unique event ID from the gateway';
COMMENT ON COLUMN webhook_events.event_type IS 'Type of webhook event (payment_intent.succeeded, etc.)';
COMMENT ON COLUMN webhook_events.signature_verified IS 'Whether the webhook signature was verified';
COMMENT ON COLUMN webhook_events.status IS 'Processing status: pending, processed, failed, ignored';
COMMENT ON COLUMN webhook_events.processing_attempts IS 'Number of times processing was attempted';

-- Create webhook_events table for tracking webhook processing and idempotency
CREATE TABLE IF NOT EXISTS webhook_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    gateway_name VARCHAR(50) NOT NULL,
    event_id VARCHAR(255) NOT NULL,
    event_type VARCHAR(100) NOT NULL,
    event_data JSONB NOT NULL,
    signature_verified BOOLEAN DEFAULT FALSE,
    processed_at TIMESTAMP WITH TIME ZONE,
    status VARCHAR(50) DEFAULT 'pending', -- pending, processed, failed, ignored
    payment_id INTEGER REFERENCES payments(id),
    program_registration_id UUID REFERENCES program_registrations(id),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    processing_attempts INTEGER DEFAULT 0,
    last_error TEXT,
    metadata JSONB DEFAULT '{}'::jsonb
);

-- Create unique index to prevent duplicate webhook processing
CREATE UNIQUE INDEX IF NOT EXISTS idx_webhook_events_gateway_event_id 
ON webhook_events(gateway_name, event_id);

-- Create indexes for efficient querying
CREATE INDEX IF NOT EXISTS idx_webhook_events_status ON webhook_events(status);
CREATE INDEX IF NOT EXISTS idx_webhook_events_created_at ON webhook_events(created_at);
CREATE INDEX IF NOT EXISTS idx_webhook_events_payment_id ON webhook_events(payment_id);
CREATE INDEX IF NOT EXISTS idx_webhook_events_event_type ON webhook_events(event_type);

-- Enable Row Level Security
ALTER TABLE webhook_events ENABLE ROW LEVEL SECURITY;

-- Create RLS policy for webhook_events (system-only access)
CREATE POLICY webhook_events_system_access ON webhook_events
    FOR ALL USING (true);

